import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null) {
  if (!acceptLanguage) return 'Not provided'

  const languages = acceptLanguage
    .split(',')
    .map((entry, index) => {
      const [language, ...parameters] = entry.trim().split(';')
      const qualityParameter = parameters.find((parameter) =>
        /^\s*q\s*=/i.test(parameter),
      )
      const quality = qualityParameter
        ? Number(qualityParameter.trim().slice(qualityParameter.indexOf('=') + 1))
        : 1

      return { language: language.trim(), quality, index }
    })
    .filter(({ language, quality }) => language.length > 0 && quality > 0 && quality <= 1)
    .sort((a, b) => b.quality - a.quality || a.index - b.index)

  return languages[0]?.language ?? 'Not provided'
}

export default async function PreferenceSummary() {
  const [cookieStore, headerStore] = await Promise.all([cookies(), headers()])
  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = getPreferredLanguage(headerStore.get('accept-language'))

  return (
    <dl>
      <dt>Theme</dt>
      <dd>{theme}</dd>
      <dt>Preferred language</dt>
      <dd>{language}</dd>
    </dl>
  )
}

